public class ApiKeyFilter implements Filter {
    @Override
    public void doFilter(ServletRequest req, ServletResponse res, FilterChain chain)
            throws IOException, ServletException {
        if (((HttpServletRequest) req).getHeader("X-Api-Key") == null) {
            ((HttpServletResponse) res).sendError(401);
            return;                              // short-circuit
        }
        chain.doFilter(req, res);                // forward
    }
}

abstract class Handler {
    private Handler successor;

    Handler link(Handler next) { this.successor = next; return next; }

    Result handle(Request r) {
        return successor == null ? Result.unhandled() : successor.handle(r);
    }
}

interface Step { Optional<Response> handle(Request r); }

static Optional<Response> run(List<Step> chain, Request r) {
    return chain.stream()
                .map(step -> step.handle(r))
                .filter(Optional::isPresent)
                .findFirst()
                .flatMap(Function.identity());   // nobody handled it -> empty
}

